package com.example.finance.notification;
import android.Manifest; import android.app.*; import android.content.*; import android.content.pm.PackageManager; import android.os.Build; import androidx.annotation.NonNull; import androidx.core.app.NotificationCompat; import androidx.core.content.ContextCompat; import androidx.work.*; import com.example.lab5.R; import com.example.finance.presentation.MainActivity;
public class ReminderWorker extends Worker { public ReminderWorker(@NonNull Context c,@NonNull WorkerParameters p){super(c,p);} @NonNull public Result doWork(){Context c=getApplicationContext(); NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE); if(Build.VERSION.SDK_INT>=26)n.createNotificationChannel(new NotificationChannel("finance","Финансовые напоминания",NotificationManager.IMPORTANCE_DEFAULT)); if(Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(c,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return Result.success(); Intent intent=new Intent(c,MainActivity.class); PendingIntent pi=PendingIntent.getActivity(c,0,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE); n.notify(getInputData().getInt("id",1),new NotificationCompat.Builder(c,"finance").setSmallIcon(R.drawable.ic_app).setContentTitle(getInputData().getString("title")).setContentText(getInputData().getString("text")).setContentIntent(pi).setAutoCancel(true).build()); return Result.success();} }
